    },
    {
      "poi_id": "p27",
      "kind": "activity",
      "must_do_id": null,
      "note": "Egg coffee whipped like a cloud over dark, strong brew. Sip it slow and watch the river wake up."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "m3",
